window.__ModuleLoader__.load({
  id: 'dsh-task-ping',
  factory(require) {
    const React = require('react')

    const TITLE = '对话任务完成'
    const BODY = '任务已处理完毕，回来看看结果。'

    // A page cannot read local files, so 054_definite-555.wav (370 KB) is inlined as a
    // URI. Regenerate with: base64 -w0 <file>, if the sound is ever changed.
    const SOUND = 'data:audio/wav;base64,'
    const SETTINGS_KEY = 'dsh-task-notify/settings'
    const SOUND_NAME = 'Definite 555（内置）'
    const DEFAULT_SETTINGS = { enabled: true, volume: 100, sound: null }

    // Fallback when the audio element is blocked (autoplay policy).
    function beep() {
      try {
        const Ctx = window.AudioContext || window.webkitAudioContext
        if (!Ctx) return
        const ctx = new Ctx()
        if (ctx.state === 'suspended') {
          const resumed = ctx.resume()
          if (resumed && typeof resumed.catch === 'function') resumed.catch(() => {})
        }
        const now = ctx.currentTime
        const osc = ctx.createOscillator()
        const gain = ctx.createGain()
        osc.type = 'sine'
        osc.frequency.value = 880
        gain.gain.setValueAtTime(0.0001, now)
        gain.gain.exponentialRampToValueAtTime(0.14, now + 0.02)
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.3)
        osc.connect(gain).connect(ctx.destination)
        osc.start(now)
        osc.stop(now + 0.32)
        window.setTimeout(() => {
          ctx.close().catch(() => {})
        }, 900)
      } catch {}
    }

    // Windows lowers other media by itself while a stream is active on the
    // communications endpoint (Control Panel -> Sound -> Communications -> "reduce
    // by 50%"). The browser cannot render there, so the sound is handed to the Host
    // half (route -> play-comm.ps1 -> WASAPI eCommunications). Nothing here lowers
    // anyone else's volume. If the Host cannot play it, this page plays it instead:
    // no ducking, but the notification is still audible.
    const HOST_PLAY_TIMEOUT_MS = 1600
    function hostPlay(dataUrl, volume) {
      return new Promise((resolve) => {
        try {
          if (typeof fetch !== 'function') {
            resolve(false)
            return
          }
          let settled = false
          const settle = (played) => {
            if (settled) return
            settled = true
            resolve(played)
          }
          window.setTimeout(() => settle(false), HOST_PLAY_TIMEOUT_MS)
          const started = fetch('/dsh-task-notify/play', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ dataUrl, volume }),
            cache: 'no-store',
          })
          if (!started || typeof started.then !== 'function') {
            settle(false)
            return
          }
          started.then((res) => settle(!!res && res.ok === true)).catch(() => settle(false))
        } catch {
          resolve(false)
        }
      })
    }

    function playSound(settings) {
      const current = settings || DEFAULT_SETTINGS
      if (current.volume <= 0) return
      const source = current.sound || SOUND
      const level = Math.max(0, Math.min(1, current.volume / 100))
      const local = () => {
        try {
          const audio = new Audio(source)
          audio.volume = level
          const started = audio.play()
          if (started && typeof started.catch === 'function') started.catch(() => beep())
        } catch {
          beep()
        }
      }
      hostPlay(source, current.volume).then((played) => {
        if (!played) local()
      })
    }

    function readSettings() {
      const fallback = { enabled: true, volume: 100, sound: null }
      try {
        const raw = window.localStorage.getItem(SETTINGS_KEY)
        if (!raw) return fallback
        const parsed = JSON.parse(raw)
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return fallback
        const volume = parsed.volume
        return {
          enabled: typeof parsed.enabled === 'boolean' ? parsed.enabled : true,
          volume:
            typeof volume === 'number' && Number.isFinite(volume) && volume >= 0 && volume <= 100
              ? Math.round(volume)
              : 100,
          sound: typeof parsed.sound === 'string' && parsed.sound.indexOf('data:audio') === 0 ? parsed.sound : null,
        }
      } catch {
        return fallback
      }
    }

    function writeSettings(settings) {
      try {
        window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
        return true
      } catch {
        return false
      }
    }

    // `notice` is the copy override used by other events (pending approval /
    // question); the turn-finished call passes none and keeps the old copy.
    function show(sessionId, summary, ctx, notice) {
      const settings = readSettings()
      // Master switch: when it is off nothing leaves the app at all — no toast, no
      // sound, no mail. The mail switch is a sub-option of this one, not a parallel one.
      if (!settings.enabled) return
      const custom = notice && typeof notice === 'object' ? notice : null
      const title =
        custom && typeof custom.title === 'string' && custom.title.trim() ? custom.title.trim() : TITLE
      const detail = custom
        ? typeof custom.body === 'string' && custom.body.trim()
          ? custom.body.trim()
          : BODY
        : typeof summary === 'string' && summary.trim()
          ? `已完成：${summary.trim()}`
          : BODY
      // Mirror the notice to the phone through the Host, which owns the SMTP account.
      // Fire and forget: a slow or unreachable mail server must never delay the toast
      // or the sound, and a Host with no account just answers 204.
      try {
        if (typeof fetch === 'function') {
          const posted = fetch('/dsh-task-notify/push', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ title, body: detail, sessionId }),
            cache: 'no-store',
          })
          if (posted && typeof posted.catch === 'function') posted.catch(() => {})
        }
      } catch {}
      try {
        if (typeof Notification === 'undefined') {
          playSound(settings)
          return
        }
        const openSession = () => {
          try {
            window.focus()
          } catch {}
          try {
            if (ctx && ctx.uiWorkspace && typeof ctx.uiWorkspace.openSession === 'function') {
              ctx.uiWorkspace.openSession(sessionId)
            }
          } catch {}
        }
        const notify = () => {
          try {
            const notification = new Notification(title, { body: detail, silent: true })
            notification.onclick = openSession
          } catch {}
        }
        if (Notification.permission === 'granted') {
          notify()
        } else if (Notification.permission !== 'denied') {
          const pending = Notification.requestPermission()
          if (pending && typeof pending.catch === 'function') {
            pending.then((result) => {
              if (result === 'granted') notify()
            }).catch(() => {})
          }
        }
      } catch {}
      playSound(settings)
    }

    // Kinds come from the Client `uiSession` pending-interaction registry:
    // PendingApproval.kind === 'approval', PendingQuestion.kind is 'question' or
    // 'plan-review'. Body carries the tool name or the first question's text.
    const PENDING_TITLE = { approval: '需要你审批', question: '需要你回答', 'plan-review': '需要你确认计划' }

    // Hook-shaped fallback: no source to read when the shell does not supply one.
    function useNoStatus(selector) {
      return selector(undefined)
    }

    function describePending(interaction, summary) {
      const kind = interaction && typeof interaction.kind === 'string' ? interaction.kind : ''
      const title = PENDING_TITLE[kind] || '需要你处理'
      let body = ''
      try {
        if (kind === 'approval') {
          const tool = typeof interaction.toolName === 'string' ? interaction.toolName.trim() : ''
          if (tool) body = `工具 ${tool} 正在等待你的审批`
        } else {
          const list = interaction.questions
          const first = Array.isArray(list)
            ? list.find((item) => item && typeof item.question === 'string' && item.question.trim())
            : null
          if (first) {
            const text = first.question.replace(/\s+/g, ' ').trim()
            body = text.length > 60 ? `${text.slice(0, 60)}…` : text
          }
        }
      } catch {}
      const fallback = typeof summary === 'string' ? summary.trim() : ''
      if (!body) body = fallback ? `会话「${fallback}」在等你处理` : '会话里有事等你处理。'
      return { title, body }
    }

    // Values copied from DeveloperToolsRow.module.css ("显示代码工作视图" row),
    // so each of these preferences reads as one of the General section's rows:
    // 16px vertical padding, .5px bottom rule, 14/20 title, 12/18 description.
    const UI = {
      section: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 24,
        padding: '16px 0',
        borderBottom: '.5px solid var(--dsw-alias-border-l2)',
        color: 'var(--dsw-alias-label-primary)',
      },
      title: { fontSize: 14, lineHeight: '20px' },
      description: { color: 'var(--dsw-alias-label-secondary)', marginTop: 4, fontSize: 12, lineHeight: '18px' },
      control: { display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto' },
      hint: { color: 'var(--dsw-alias-label-secondary)', fontSize: 12, lineHeight: '18px' },
      // Host `.sm .outline` button (index CSS `._button_1rv3m_2` / `._sm_1rv3m_28`
      // / `._outline_1rv3m_54`): 28px tall, thin .5px border, radius-sm corners.
      button: {
        boxSizing: 'border-box',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 4,
        height: 28,
        padding: '0 10px',
        border: '.5px solid var(--dsw-alias-border-l3, var(--dsw-alias-border-l2))',
        borderRadius: 'var(--dsw-radius-sm, 8px)',
        background: 'transparent',
        color: 'var(--dsw-alias-label-primary)',
        font: 'inherit',
        fontSize: 12,
        lineHeight: '18px',
        whiteSpace: 'nowrap',
        cursor: 'pointer',
      },
      notice: { color: 'var(--dsw-alias-state-error-primary, #d9534f)', fontSize: 12, lineHeight: '18px' },
      noticeBox: { padding: '8px 0' },
      ok: { color: 'var(--dsw-alias-state-success-primary, #2e7d32)', fontSize: 12, lineHeight: '18px' },
      field: { display: 'flex', flexDirection: 'column', gap: 4, marginBottom: 10 },
      label: { color: 'var(--dsw-alias-label-secondary)', fontSize: 12, lineHeight: '18px' },
      input: {
        boxSizing: 'border-box',
        width: '100%',
        height: 28,
        padding: '0 8px',
        border: '.5px solid var(--dsw-alias-border-l3, var(--dsw-alias-border-l2))',
        borderRadius: 'var(--dsw-radius-sm, 8px)',
        background: 'transparent',
        color: 'var(--dsw-alias-label-primary)',
        font: 'inherit',
        fontSize: 12,
        lineHeight: '18px',
        outline: 'none',
      },
      form: { padding: '4px 0 12px', maxWidth: 420 },
    }

    /** One General-style preference row: copy on the left, its control on the right. */
    function Row(props) {
      const h = React.createElement
      return h(
        'div',
        { style: props.disabled ? { ...UI.section, opacity: 0.5 } : UI.section },
        h(
          'div',
          { style: { minWidth: 0 } },
          h('div', { style: UI.title }, props.title),
          props.description ? h('div', { style: UI.description }, props.description) : null,
        ),
        h('div', { style: UI.control }, props.children),
      )
    }

    /** Host-style small outline button; inline styles cannot express :hover. */
    function Button(props) {
      const h = React.createElement
      const [hover, setHover] = React.useState(false)
      const disabled = props.disabled === true
      const base = disabled ? { ...UI.button, opacity: 0.5, cursor: 'default' } : UI.button
      return h(
        'button',
        {
          type: 'button',
          disabled,
          onClick: disabled ? undefined : props.onClick,
          onMouseEnter: () => setHover(!disabled),
          onMouseLeave: () => setHover(false),
          style: hover && !disabled ? { ...base, background: 'var(--dsw-alias-interactive-bg-hover)' } : base,
        },
        props.children,
      )
    }

    // Copy of the host switch (index CSS `._switch_1ik0f_5` / `._thumb_1ik0f_33`):
    // 36x20 pill, brand track when on, 16px thumb translated by 16px.
    function Switch(props) {
      const h = React.createElement
      const checked = props.checked === true
      const disabled = props.disabled === true
      return h(
        'button',
        {
          type: 'button',
          role: 'switch',
          className: 'dtn-switch',
          'aria-checked': checked,
          'aria-label': props.label,
          disabled,
          onClick: () => {
            if (disabled) return
            if (props.onChange) props.onChange(!checked)
          },
          style: {
            boxSizing: 'border-box',
            position: 'relative',
            flex: '0 0 auto',
            width: 36,
            height: 20,
            padding: 2,
            border: 0,
            borderRadius: 999,
            background: checked
              ? 'var(--dsw-alias-brand-primary)'
              : 'var(--dsw-alias-border-l3, var(--dsw-alias-border-l2))',
            cursor: disabled ? 'default' : 'pointer',
            opacity: disabled ? 0.5 : 1,
          },
        },
        h('span', {
          className: 'dtn-switch-thumb',
          style: {
            display: 'block',
            width: 16,
            height: 16,
            borderRadius: 999,
            clipPath: 'circle(50%)',
            background: checked
              ? 'var(--dsw-alias-label-primary-foreground, #fff)'
              : 'var(--dsw-alias-switch-thumb, #fff)',
            transition: 'transform .12s ease',
            transform: checked ? 'translateX(16px)' : 'none',
          },
        }),
      )
    }

    const MAIL_CONFIG_ROUTE = '/dsh-task-notify/push/config'
    const MAIL_TEST_ROUTE = '/dsh-task-notify/push/test'
    const EMPTY_MAIL = {
      enabled: false,
      host: 'smtp.qq.com',
      port: 465,
      secure: true,
      user: '',
      pass: '',
      fromName: 'DSH',
      to: '',
    }

    // Common providers: picking one fills host/port/TLS so nobody has to remember
    // whether QQ wants 465 or 587. `secure: false` means STARTTLS on 587.
    const MAIL_PRESETS = [
      { id: 'qq', label: 'QQ 邮箱', host: 'smtp.qq.com', port: 465, secure: true, domains: ['qq.com', 'vip.qq.com', 'foxmail.com'] },
      { id: '163', label: '网易 163', host: 'smtp.163.com', port: 465, secure: true, domains: ['163.com'] },
      { id: '126', label: '网易 126', host: 'smtp.126.com', port: 465, secure: true, domains: ['126.com'] },
      { id: 'exmail', label: '腾讯企业邮箱', host: 'smtp.exmail.qq.com', port: 465, secure: true, domains: ['exmail.qq.com'] },
      { id: 'outlook', label: 'Outlook / Hotmail', host: 'smtp-mail.outlook.com', port: 587, secure: false, domains: ['outlook.com', 'hotmail.com', 'live.com', 'msn.com'] },
      { id: 'gmail', label: 'Gmail', host: 'smtp.gmail.com', port: 465, secure: true, domains: ['gmail.com', 'googlemail.com'] },
      { id: 'custom', label: '自定义', host: '', port: 465, secure: true, domains: [] },
    ]

    function presetForEmail(email) {
      const domain = String(email || '').split('@')[1]
      if (!domain || domain.indexOf('.') < 0) return null
      const wanted = domain.trim().toLowerCase()
      return MAIL_PRESETS.find((item) => item.domains.includes(wanted)) || null
    }

    function presetForHost(host) {
      const wanted = String(host || '').trim().toLowerCase()
      if (!wanted) return null
      return MAIL_PRESETS.find((item) => item.host === wanted) || null
    }

    function postJson(route, payload) {
      return fetch(route, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
        cache: 'no-store',
      }).then((res) => res.json().catch(() => ({ ok: false, error: 'HTTP ' + res.status })))
    }

    function MailField(props) {
      const h = React.createElement
      const disabled = props.disabled === true
      return h(
        'label',
        { style: disabled ? { ...UI.field, opacity: 0.5 } : UI.field },
        h('span', { style: UI.label }, props.label),
        h('input', {
          type: props.type || 'text',
          value: props.value,
          placeholder: props.placeholder,
          disabled,
          style: disabled ? { ...UI.input, cursor: 'default' } : UI.input,
          autoComplete: 'off',
          spellCheck: false,
          onChange: (event) => {
            if (disabled) return
            if (props.onChange) props.onChange(event.currentTarget.value)
          },
        }),
      )
    }

    // Settings form for the mail mirror. Everything is stored by the Host in
    // `~/.dsh/dsh-task-notify-push.json`; this page only reads and posts to it, so
    // nothing sensitive ends up in localStorage.
    function MailSettings(props) {
      const h = React.createElement
      const locked = props && props.disabled === true
      const [draft, setDraft] = React.useState(null)
      const [saved, setSaved] = React.useState(null)
      const [busy, setBusy] = React.useState('')
      const [message, setMessage] = React.useState(null)
      const [open, setOpen] = React.useState(false)
      const [showPass, setShowPass] = React.useState(false)
      const draftRef = React.useRef(null)
      draftRef.current = draft

      React.useEffect(() => {
        let alive = true
        try {
          fetch(MAIL_CONFIG_ROUTE, { cache: 'no-store' })
            .then((res) => res.json())
            .then((json) => {
              if (!alive) return
              const cfg = { ...EMPTY_MAIL, ...(json && json.config ? json.config : {}) }
              setSaved(cfg)
              setDraft(cfg)
              if (cfg.enabled) setOpen(true)
            })
            .catch(() => {
              if (!alive) return
              setSaved(EMPTY_MAIL)
              setDraft(EMPTY_MAIL)
            })
        } catch {
          setSaved(EMPTY_MAIL)
          setDraft(EMPTY_MAIL)
        }
        return () => {
          alive = false
        }
      }, [])

      if (!draft) {
        return h(Row, { title: '邮件推送', description: '读取配置中…' }, null)
      }

      const patch = (changes) => setDraft({ ...draftRef.current, ...changes })

      const save = () => {
        setBusy('save')
        setMessage(null)
        postJson(MAIL_CONFIG_ROUTE, draftRef.current)
          .then((json) => {
            if (json && json.ok) {
              setSaved(draftRef.current)
              setMessage(
                json.warning
                  ? { kind: 'err', text: '已保存，但 ' + json.warning }
                  : { kind: 'ok', text: '已保存，下一封通知就按新配置发' },
              )
            } else {
              setMessage({ kind: 'err', text: (json && json.error) || '保存失败' })
            }
          })
          .catch((err) => setMessage({ kind: 'err', text: '保存失败：' + err.message }))
          .finally(() => setBusy(''))
      }

      const test = () => {
        setBusy('test')
        setMessage(null)
        postJson(MAIL_CONFIG_ROUTE, draftRef.current)
          .then((json) => {
            if (!json || !json.ok) throw new Error((json && json.error) || '保存失败')
            setSaved(draftRef.current)
            return postJson(MAIL_TEST_ROUTE, {})
          })
          .then((json) => {
            if (json && json.ok) setMessage({ kind: 'ok', text: '测试邮件已发出 → ' + json.to })
            else setMessage({ kind: 'err', text: (json && json.error) || '发送失败' })
          })
          .catch((err) => setMessage({ kind: 'err', text: err.message }))
          .finally(() => setBusy(''))
      }

      const header = h(
        'div',
        { style: locked ? { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 24, opacity: 0.5 } : { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 24 } },
        h(
          'div',
          { style: { minWidth: 0 } },
          h('div', { style: UI.title }, '邮件推送'),
          h(
            'div',
            { style: UI.description },
            locked ? '总开关关闭时，所有通知（含邮件）都会停用' : '同一份提醒再发一封邮件到手机，人不在电脑前也能看到',
          ),
        ),
        h(Switch, {
          checked: draft.enabled === true,
          disabled: locked,
          label: '启用邮件推送',
          onChange: (enabled) => {
            patch({ enabled })
            setOpen(true)
          },
        }),
      )

      const preset = presetForHost(draft.host)
      const presetId = preset ? preset.id : 'custom'

      const body = open
        ? h(
            'div',
            { style: locked ? { ...UI.form, opacity: 0.5 } : UI.form },
            h(
              'label',
              { style: UI.field },
              h('span', { style: UI.label }, '邮箱类型（选中后自动填服务器和端口）'),
              h(
                'select',
                {
                  disabled: locked,
                  style: locked ? { ...UI.input, cursor: 'default' } : UI.input,
                  value: presetId,
                  onChange: (event) => {
                    if (locked) return
                    const picked = MAIL_PRESETS.find((item) => item.id === event.currentTarget.value)
                    if (picked && picked.host) {
                      patch({ host: picked.host, port: picked.port, secure: picked.secure })
                    }
                  },
                },
                MAIL_PRESETS.map((item) => h('option', { key: item.id, value: item.id }, item.label)),
              ),
            ),
            h(
              'div',
              { style: { display: 'flex', gap: 10 } },
              h(
                'div',
                { style: { flex: '2 1 0' } },
                h(MailField, {
                  disabled: locked,
                  label: 'SMTP 服务器',
                  value: draft.host,
                  placeholder: 'smtp.qq.com',
                  onChange: (v) => patch({ host: v }),
                }),
              ),
              h(
                'div',
                { style: { flex: '1 1 0' } },
                h(MailField, {
                  disabled: locked,
                  label: '端口',
                  value: String(draft.port || 465),
                  placeholder: '465',
                  onChange: (v) => patch({ port: v }),
                }),
              ),
            ),
            h(MailField, {
              disabled: locked,
              label: '发件邮箱（填完自动识别服务商）',
              value: draft.user,
              placeholder: 'you@qq.com',
              onChange: (v) => {
                const guess = presetForEmail(v)
                if (guess && guess.host) patch({ user: v, host: guess.host, port: guess.port, secure: guess.secure })
                else patch({ user: v })
              },
            }),
            h(
              'div',
              { style: UI.field },
              h(
                'div',
                { style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between' } },
                h('span', { style: UI.label }, '授权码（邮箱设置里生成的，不是登录密码）'),
                h(
                  'button',
                  {
                    type: 'button',
                    disabled: locked,
                    style: locked
                      ? { ...UI.button, height: 20, padding: '0 6px', fontSize: 11, opacity: 0.5, cursor: 'default' }
                      : { ...UI.button, height: 20, padding: '0 6px', fontSize: 11 },
                    onClick: () => {
                      if (!locked) setShowPass(!showPass)
                    },
                  },
                  showPass ? '隐藏' : '显示',
                ),
              ),
              h('input', {
                type: showPass ? 'text' : 'password',
                value: draft.pass,
                disabled: locked,
                style: locked ? { ...UI.input, cursor: 'default' } : UI.input,
                autoComplete: 'off',
                spellCheck: false,
                onChange: (event) => {
                  if (!locked) patch({ pass: event.currentTarget.value })
                },
              }),
              h('span', { style: UI.label }, '不想把授权码写进文件？填 env:DSH_SMTP_PASS，改为从环境变量读取'),
            ),
            h(MailField, {
              disabled: locked,
              label: '收件邮箱（留空则发到发件邮箱）',
              value: draft.to,
              placeholder: 'you@qq.com',
              onChange: (v) => patch({ to: v }),
            }),
            h(MailField, {
              disabled: locked,
              label: '发件人名称',
              value: draft.fromName,
              placeholder: 'DSH',
              onChange: (v) => patch({ fromName: v }),
            }),
            h(
              'div',
              { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' } },
              h(Button, { disabled: locked, onClick: save }, busy === 'save' ? '保存中…' : '保存'),
              h(Button, { disabled: locked, onClick: test }, busy === 'test' ? '发送中…' : '发送测试邮件'),
              saved && saved.enabled
                ? h('span', { style: UI.hint }, '当前：已启用')
                : h('span', { style: UI.hint }, '当前：未启用'),
            ),
            message ? h('div', { style: { paddingTop: 8, ...(message.kind === 'ok' ? UI.ok : UI.notice) } }, message.text) : null,
          )
        : null

      return h(
        'div',
        { style: { padding: '16px 0', borderBottom: '.5px solid var(--dsw-alias-border-l2)' } },
        header,
        body,
      )
    }

    function NotifySettingsRow() {
      const h = React.createElement
      const [settings, setSettings] = React.useState(readSettings)
      const [notice, setNotice] = React.useState('')
      const fileRef = React.useRef(null)
      const settingsRef = React.useRef(settings)
      settingsRef.current = settings

      const preview = (value) => playSound({ sound: value.sound, volume: value.volume })

      const save = (next) => {
        setSettings(next)
        setNotice(writeSettings(next) ? '' : '文件过大，本次生效但不保存')
        return next
      }

      const patch = (changes) => save({ ...settingsRef.current, ...changes })
      // The master switch turns every channel off and locks the sub-rows.
      const locked = settings.enabled !== true

      const onFileChange = (event) => {
        const input = event.currentTarget
        const file = input.files && input.files[0]
        if (!file) return
        const reader = new FileReader()
        reader.onload = () => {
          const dataUrl = typeof reader.result === 'string' ? reader.result : null
          if (!dataUrl) {
            setNotice('读取文件失败，已保留原音效')
            return
          }
          const next = save({ ...settingsRef.current, sound: dataUrl })
          preview(next)
        }
        reader.onerror = () => setNotice('读取文件失败，已保留原音效')
        reader.readAsDataURL(file)
        input.value = ''
      }

      const changeVolume = (event) => {
        const volume = Number(event.currentTarget.value)
        setSettings((prev) => ({ ...prev, volume: Number.isFinite(volume) ? volume : 100 }))
      }

      const commitVolume = (value) => {
        const volume = Number(value)
        const next = save({ ...settingsRef.current, volume: Number.isFinite(volume) ? volume : 100 })
        preview(next)
      }

      return h(
        React.Fragment,
        null,
        h(
          Row,
          { title: '任务完成通知', description: '总开关：关闭后弹窗、提示音和邮件推送全部停用，下面的选项也会锁定' },
          h(Switch, {
            checked: settings.enabled,
            label: '启用任务完成通知',
            onChange: (enabled) => patch({ enabled }),
          }),
        ),
        h(
          Row,
          { title: '通知音效', description: settings.sound ? '自定义音频' : SOUND_NAME, disabled: locked },
          h(
            Button,
            {
              disabled: locked,
              onClick: () => {
                if (locked) return
                if (fileRef.current) fileRef.current.click()
              },
            },
            '选择文件…',
          ),
          h(Button, { disabled: locked, onClick: () => patch({ sound: null }) }, '恢复默认'),
          h('input', {
            ref: fileRef,
            type: 'file',
            accept: 'audio/*',
            disabled: locked,
            onChange: onFileChange,
            style: { display: 'none' },
          }),
        ),
        h(
          Row,
          { title: '通知音量', description: '松开滑块后按此音量试听', disabled: locked },
          h('span', { style: UI.hint }, settings.volume + '%'),
          h('input', {
            type: 'range',
            min: 0,
            max: 100,
            step: 1,
            value: settings.volume,
            className: 'dtn-range',
            'aria-label': '通知音效音量',
            disabled: locked,
            onChange: changeVolume,
            onPointerUp: (event) => {
              if (!locked) commitVolume(event.currentTarget.value)
            },
            onKeyUp: (event) => {
              if (!locked) commitVolume(event.currentTarget.value)
            },
            style: { '--dtn-fill': settings.volume + '%' },
          }),
        ),
        notice ? h('div', { style: UI.noticeBox }, notice) : null,
        h(MailSettings, { disabled: locked }),
      )
    }

    // What the finished task was: the `title` projection (session-title package
    // registers it, string|null), then the list's displayTitle, then the last
    // user message. Hooks are called unconditionally so the order never changes.
    function useTaskSummary(props, sessionId) {
      const useProjection = props.useProjection
      const useSessions = props.useSessions
      const useChat = props.useChat
      const title = typeof useProjection === 'function' ? useProjection('title') : null
      const entry =
        typeof useSessions === 'function'
          ? useSessions((snapshot) => (snapshot && snapshot.byId ? snapshot.byId[sessionId] : undefined))
          : undefined
      const order = typeof useChat === 'function' ? useChat((snapshot) => (snapshot ? snapshot.order : undefined)) : undefined
      const nodes = typeof useChat === 'function' ? useChat((snapshot) => (snapshot ? snapshot.nodes : undefined)) : undefined

      if (typeof title === 'string' && title.trim()) return title.trim()
      try {
        if (Array.isArray(order) && nodes && typeof nodes.get === 'function') {
          for (let index = order.length - 1; index >= 0; index -= 1) {
            const node = nodes.get(order[index])
            if (!node || (node.kind !== 'user' && node.kind !== 'steering')) continue
            const blocks = node.data && node.data.content
            if (!Array.isArray(blocks)) continue
            const text = blocks
              .filter((block) => block && block.type === 'text' && typeof block.text === 'string')
              .map((block) => block.text)
              .join(' ')
              .replace(/\s+/g, ' ')
              .trim()
            if (text) return text.length > 40 ? `${text.slice(0, 40)}…` : text
          }
        }
      } catch {}
      const display = entry && (entry.displayTitle || entry.title)
      return typeof display === 'string' ? display.trim() : ''
    }

    // Renders nothing. It watches the mounted session's running flag and raises
    // the notification on the true -> false edge, i.e. when a turn stops; it also
    // raises one whenever the session starts waiting for an approval or an answer.
    function TaskNotify(props, ctx) {
      const useSession = props.useSession
      const useSessionStatus = props.useSessionStatus
      const wasRunning = React.useRef(false)
      const sessionId = props.sessionId
      // Switching conversations does not remount this entry, so a stored
      // "was running" from the previous conversation must not leak into this one.
      const lastSession = React.useRef(sessionId)
      // One notification per request key (approval: <n> / question: <session>:<callId>).
      // A hidden question panel re-publishes the same key when revealed, so keys are
      // remembered instead of reset on leave; the book is only dropped per session.
      const notifiedPending = React.useRef(null)
      if (notifiedPending.current === null) notifiedPending.current = new Map()

      let running = null
      let isRoot = false
      let pendingEntry
      if (typeof useSession === 'function') {
        const value = useSession((snapshot) =>
          snapshot && typeof snapshot.running === 'boolean' ? snapshot.running : null,
        )
        running = typeof value === 'boolean' ? value : null
        // Subagent conversations are not the task the user is waiting on.
        const root = useSession((snapshot) => (snapshot ? snapshot.subagent == null : false))
        isRoot = root === true
      }
      // `uiSession` root source: sessionId -> { running, pendingInteraction, completionUnread }.
      // The fallback keeps the Hook call unconditional, so the call order never moves.
      const useStatus = typeof useSessionStatus === 'function' ? useSessionStatus : useNoStatus
      pendingEntry = useStatus((status) => {
        try {
          return status && typeof status.get === 'function' ? status.get(sessionId) : undefined
        } catch {
          return undefined
        }
      })
      const interaction = pendingEntry && typeof pendingEntry === 'object' ? pendingEntry.pendingInteraction : undefined
      // A read-only review card replays a settled question; it is not a request.
      const pendingKey =
        interaction && typeof interaction.key === 'string' && interaction.review === undefined ? interaction.key : null
      const summary = useTaskSummary(props, sessionId)
      const pendingNotice = pendingKey ? describePending(interaction, summary) : null
      // The effect fires on the pending key only, so the newest copy is read through a ref.
      const pendingNoticeRef = React.useRef(null)
      pendingNoticeRef.current = pendingNotice
      // The effect fires on the running edge only, so read the newest title through
      // a ref instead of adding it to the dependency list.
      const summaryRef = React.useRef(summary)
      summaryRef.current = summary

      React.useEffect(() => {
        if (!pendingKey || !isRoot) return
        let keys = notifiedPending.current.get(sessionId)
        if (keys === undefined) {
          keys = new Set()
          notifiedPending.current.set(sessionId, keys)
        }
        if (keys.has(pendingKey)) return
        keys.add(pendingKey)
        if (keys.size > 50) keys.delete(keys.values().next().value)
        const notice = pendingNoticeRef.current
        if (notice) show(sessionId, '', ctx, notice)
      }, [pendingKey, sessionId, isRoot])

      React.useEffect(() => {
        if (lastSession.current !== sessionId) {
          lastSession.current = sessionId
          wasRunning.current = false
          return
        }
        if (running === null || !isRoot) return
        if (running) {
          wasRunning.current = true
          return
        }
        if (!wasRunning.current) return
        wasRunning.current = false
        show(sessionId, summaryRef.current, ctx)
      }, [running, isRoot, sessionId])

      // Chromium only grants notification permission from a user gesture.
      React.useEffect(() => {
        if (typeof Notification === 'undefined' || Notification.permission === 'granted') return undefined
        const ask = () => {
          try {
            const pending = Notification.requestPermission()
            if (pending && typeof pending.catch === 'function') pending.catch(() => {})
          } catch {}
        }
        ask()
        document.addEventListener('pointerdown', ask)
        return () => document.removeEventListener('pointerdown', ask)
      }, [])

      return null
    }

    // The inline `border-radius: 999px` rendered as an 8px corner in practice (measured
    // off screenshots), so the pill shape is asserted from a stylesheet instead. The
    // slider is drawn here too: the host has no range control, so it borrows the
    // switch's language (brand fill, border-l3 track) instead of the browser default.
    const PLUGIN_CSS = [
      '.dtn-switch{border-radius:999px!important;corner-shape:round}',
      // border-radius on the thumb did not take effect in this page, so the circle is
      // asserted twice: the radius and a clip path that does not depend on it.
      '.dtn-switch .dtn-switch-thumb{border-radius:999px!important;clip-path:circle(50%)!important;',
      'overflow:hidden;box-sizing:border-box;flex:0 0 auto}',
      '.dtn-range{-webkit-appearance:none;appearance:none;width:160px;height:20px;margin:0;padding:0;',
      'background:transparent;cursor:pointer}',
      '.dtn-range::-webkit-slider-runnable-track{height:4px;border-radius:999px;background:',
      'linear-gradient(to right,var(--dsw-alias-brand-primary) 0 var(--dtn-fill,50%),',
      'var(--dsw-alias-border-l3,var(--dsw-alias-border-l2)) var(--dtn-fill,50%) 100%)}',
      '.dtn-range::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:16px;height:16px;',
      'margin-top:-6px;border-radius:50%;background:var(--dsw-alias-brand-primary);',
      'box-shadow:0 0 0 2px var(--dsw-alias-bg-layer-1,transparent)}',
      '.dtn-range:focus-visible{outline:var(--dsw-focus-ring-width,2px) solid ',
      'var(--dsw-focus-ring-color,var(--dsw-alias-brand-primary));outline-offset:4px;border-radius:999px}',
    ].join('')

    return {
      inject: ['slots', 'uiWorkspace'],
      // Test hook: lets verify-ui.mjs drive `show()` and the settings tree without a
      // browser. Not used by the Host or any other module.
      __test: { show },
      apply(ctx) {
        ctx.effect(() => {
          const tag = document.createElement('style')
          tag.dataset.plugin = 'dsh-task-notify'
          tag.textContent = PLUGIN_CSS
          document.head.appendChild(tag)
          return () => tag.remove()
        }, 'dsh-task-notify: plugin css')
        // Both registrations defer until their slot is declared, so activation
        // order between this module and the settings page does not matter.
        const disposers = [
          ctx.slots.inject('settings.general.item', () =>
            ctx.slots.register({ name: 'settings.general.item', id: 'task-notify', order: 31 }, NotifySettingsRow),
          ),
          ctx.slots.inject('conversation.composer.dock', () =>
            ctx.slots.register({ name: 'conversation.composer.dock', id: 'task-notify', order: 90 }, (props) =>
              TaskNotify(props, ctx),
            ),
          ),
        ]
        return () => {
          for (const dispose of disposers) {
            if (typeof dispose === 'function') {
              try {
                dispose()
              } catch {}
            }
          }
        }
      },
    }
  },
})
